          "component": "Row",
          "align": "start",
          "children": [
            "sec_h1",
            "sec_h2"
          ]
        },
        {
          "id": "sec_h1",
          "component": "Text",
          "text": "Technique",
          "variant": "h4",
          "weight": 1
        },
        {
          "id": "sec_h2",
          "component": "Text",
          "text": "Why it works",
          "variant": "h4",
          "weight": 2
        },
        {
          "id": "sec_row_1",
          "component": "Row",
          "align": "start",
          "children": [
            "sec_r1_c1",
            "sec_r1_c2"
          ]
        },
        {
          "id": "sec_r1_c1",
          "component": "Text",
          "text": "Do Not Rinse",
          "weight": 1
        },
        {
          "id": "sec_r1_c2",
          "component": "Text",
          "text": "Retains the surface starch on the arborio rice, which is essential for thickening the broth.",
          "weight": 2
        },
        {
          "id": "sec_row_2",
          "component": "Row",
          "align": "start",
          "children": [
            "sec_r2_c1",
            "sec_r2_c2"
          ]
        },
        {
          "id": "sec_r2_c1",
          "component": "Text",
          "text": "Hot Broth Only",
          "weight": 1
        },
        {
          "id": "sec_r2_c2",
          "component": "Text",
          "text": "Adding cold broth shocks the rice and stops the cooking process; keeping broth hot ensures consistent starch release.",
          "weight": 2
        },
        {
